actions.script:
                import org.slf4j.LoggerFactory
                def logger = LoggerFactory.getLogger("GlobalEinvoiceServices")

                // Step 1: Generate Standard Agnostic JSON payload representing the Invoice
                def agnosticInvoiceData = [
                    invoiceNumber: invoice.invoiceId,
                    invoiceDate: invoice.invoiceDate,
                    currency: invoice.currencyUomId,
                    totalAmount: invoice.invoiceTotal,
                    // In production, this would deeply fetch Party details and InvoiceItems
                    lineItems: [
                        [ description: "Consulting Services", amount: 1500.00 ],
                        [ description: "Software License", amount: 3000.00 ]
                    ]
                ]

                if (!configs) {
                    logger.info("No E-Invoicing configured for Tenant [${tenantId}]. Skipping electronic dispatch.")
                    dispatchStatus = "SKIPPED"
                    return
                }

                def config = configs[0]
                String standard = config.eInvoiceStandardEnumId

                // Step 2 & 3: Route to the localized Formatter Adapter
                String formattedPayload = ""
                if (standard == "EisPeppolUbl") {
                    logger.info("Formatting Invoice [${invoiceId}] to EU PEPPOL UBL 2.1 XML Standard.")
                    // Call the PeppolUblFormatter adapter
                    formattedPayload = formatPeppolUbl(agnosticInvoiceData)
                } else if (standard == "EisFacturae") {
                    logger.info("Formatting Invoice [${invoiceId}] to LATAM Facturae XML Standard.")
                    formattedPayload = "<Facturae>...</Facturae>"
                } else if (standard == "EisGstJson") {
                    logger.info("Formatting Invoice [${invoiceId}] to India GST JSON Standard.")
                    formattedPayload = "{ \"gstn\": \"...\" }"
                }

                // Step 4: Dispatch payload to external Compliance Middleware (Avalara, Edicom, Sovos)
                // This keeps Zenith's core decoupled from changing government APIs.
                logger.info("Dispatching Formatted Payload to Compliance Middleware API...")

                dispatchStatus = "SUCCESS"
                governmentReferenceId = "PEPPOL-" + java.util.UUID.randomUUID().toString().substring(0, 8)

                logger.info("E-Invoice [${invoiceId}] dispatched successfully. Government Ref: ${governmentReferenceId}")


                // Inner helper method for the Adapter
                String formatPeppolUbl(Map data) {
                    // Generates the rigid EU PEPPOL UBL XML Structure
                    return """<?xml version="1.0" encoding="UTF-8"?>
<Invoice xmlns="urn:oasis:names:specification:ubl:schema:xsd:Invoice-2"
         xmlns:cac="urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2"
         xmlns:cbc="urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2">
    <cbc:CustomizationID>urn:cen.eu:en16931:2017#compliant#urn:fdc:peppol.eu:2017:poacc:billing:3.0</cbc:CustomizationID>
    <cbc:ID>${data.invoiceNumber}</cbc:ID>
    <cbc:IssueDate>${data.invoiceDate}</cbc:IssueDate>
    <cbc:DocumentCurrencyCode>${data.currency}</cbc:DocumentCurrencyCode>
    <cac:LegalMonetaryTotal>
        <cbc:TaxExclusiveAmount currencyID="${data.currency}">${data.totalAmount}</cbc:TaxExclusiveAmount>
        <cbc:PayableAmount currencyID="${data.currency}">${data.totalAmount}</cbc:PayableAmount>
    </cac:LegalMonetaryTotal>
</Invoice>"""
                }
